defmodule ExHdl.Test.GnuRadioFixture do
  @moduledoc false
  # Shared DSP cases (test/dsp_cases/*.json) and the GNU Radio output for
  # them (test/fixtures/gnuradio/<case>/, regenerated by
  # scripts/gnuradio_golden.sh).

  alias ExHdl.DSP

  @cases_dir Path.expand("../dsp_cases", __DIR__)
  @fixtures_dir Path.expand("../fixtures/gnuradio", __DIR__)

  def cases_dir, do: @cases_dir
  def fixtures_dir, do: @fixtures_dir

  def case_paths, do: @cases_dir |> Path.join("*.json") |> Path.wildcard() |> Enum.sort()

  def read_case(path), do: path |> File.read!() |> JSON.decode!()

  @doc """
  Loads the GNU Radio data for `case` from `root`. Fails if it was generated
  from a different version of the case file.
  """
  def load(case, case_path, root \\ @fixtures_dir) do
    dir = Path.join(root, case["name"])
    manifest = dir |> Path.join("manifest.json") |> File.read!() |> JSON.decode!()
    sha = :crypto.hash(:sha256, File.read!(case_path)) |> Base.encode16(case: :lower)

    if manifest["case_sha256"] != sha do
      raise "GNU Radio data for #{case["name"]} is stale (case file changed): run scripts/gnuradio_golden.sh"
    end

    input = for <<v::little-signed-16 <- File.read!(Path.join(dir, "input.s16le"))>>, do: v
    reference = for <<v::little-float-32 <- File.read!(Path.join(dir, "gnuradio.f32le"))>>, do: v

    if complex?(case),
      do: %{manifest: manifest, input: pairs(input), reference: pairs(reference)},
      else: %{manifest: manifest, input: input, reference: reference}
  end

  defp complex?(case), do: case["input"]["type"] == "complex"
  defp pairs(list), do: list |> Enum.chunk_every(2) |> Enum.map(&List.to_tuple/1)

  @doc "Runs the case's ExHdl kernel over `input`; returns outputs scaled so 1.0 = 32768."
  def run_exhdl(case, input) do
    %{"kernel" => kernel, "state" => state, "args" => args} = ex = case["exhdl"]
    params = case["params"]

    kernel_opts =
      Map.new(ex["kernel_opts"] || %{}, fn {k, v} -> {String.to_atom(k), value(v, params)} end)

    arity = 2 + length(args) + if(kernel_opts == %{}, do: 0, else: 1)
    fun = Function.capture(ExHdl.Test.DSP, String.to_atom(kernel), arity)

    samples =
      if complex?(case),
        do: Enum.map(input, fn {i, q} -> {Nx.s16(i), Nx.s16(q)} end),
        else: Enum.map(input, &Nx.s16/1)

    opts = if kernel_opts == %{}, do: [], else: [kernel_opts: Keyword.new(kernel_opts)]

    {outputs, _state} =
      DSP.run_scan(fun, samples, tensor(state, params), Enum.map(args, &tensor(&1, params)), opts)

    Enum.map(outputs, fn
      {i, q} -> {Nx.to_number(i) / 32768, Nx.to_number(q) / 32768}
      x -> Nx.to_number(x) / 32768
    end)
  end

  defp value(name, params) when is_binary(name), do: Map.fetch!(params, name)
  defp value(v, _params), do: v

  # State/argument specs: ["s16", 0], ["u16", "param"], ["s16", {"zeros": 30}]
  # or {"tuple": [spec, ...]}.
  defp tensor(%{"tuple" => specs}, params),
    do: specs |> Enum.map(&tensor(&1, params)) |> List.to_tuple()

  defp tensor([type, %{"zeros" => n}], _params),
    do: Nx.broadcast(Nx.tensor(0, type: String.to_atom(type)), {n})

  defp tensor([type, v], params), do: Nx.tensor(value(v, params), type: String.to_atom(type))

  @doc "SNR in dB of `signal` against `reference`."
  def snr_db(reference, signal) do
    {power, error} =
      Enum.zip(reference, signal)
      |> Enum.reduce({0.0, 0.0}, fn {r, s}, {p, e} -> {p + mag2(r), e + mag2(sub(s, r))} end)

    10 * :math.log10(power / max(error, 1.0e-300))
  end

  @doc "`{max error in Q15 LSB, sample index}`."
  def worst_sample(reference, signal) do
    Enum.zip(reference, signal)
    |> Enum.with_index()
    |> Enum.map(fn {{r, s}, i} -> {:math.sqrt(mag2(sub(s, r))) * 32768, i} end)
    |> Enum.max()
  end

  defp sub({a, b}, {c, d}), do: {a - c, b - d}
  defp sub(a, b), do: a - b
  defp mag2({a, b}), do: a * a + b * b
  defp mag2(a), do: a * a
end
